import{at as e,it as t,n,vt as r}from"./chunks/framework.BPeR9Rpo.js";var i=JSON.parse(`{"title":"Installation","description":"","frontmatter":{"title":"Installation","covers":{"screens":[],"stories":[]}},"headers":[],"relativePath":"setup/installation.md","filePath":"setup/installation.md"}`),a={name:`setup/installation.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to “Installation”">​</a></h1><p>OEA consists of a PostgreSQL database, a one-shot migration step and the backend. The backend also serves the web portal, on the same address and port as the API. The operator file <code>compose.yaml</code> in the repository starts all three with Docker Compose (or Podman Compose). If you run your own PostgreSQL, follow <a href="#your-own-postgresql">Your own PostgreSQL</a>.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to “Requirements”">​</a></h2><ul><li>Docker with Compose v2, or Podman with Compose</li><li>PostgreSQL 15 or later if you use your own database (the Compose setup uses PostgreSQL 18)</li><li>A file for the key-encryption key, readable by the container user</li></ul><h2 id="install-with-docker-compose" tabindex="-1">Install with Docker Compose <a class="header-anchor" href="#install-with-docker-compose" aria-label="Permalink to “Install with Docker Compose”">​</a></h2><ol><li><p>Copy <code>.env.example</code> to <code>.env</code> and fill in <strong>every</strong> value. Use long random values (at least 16 characters); known development values are rejected. Never commit <code>.env</code>.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Purpose</th></tr></thead><tbody><tr><td><code>POSTGRES_PASSWORD</code></td><td>PostgreSQL superuser, used only by the provisioning script on the first start</td></tr><tr><td><code>OEA_OWNER_PASSWORD</code>, <code>OEA_REPORTING_OWNER_PASSWORD</code></td><td>owner roles of the migration step</td></tr><tr><td><code>OEA_APP_PASSWORD</code></td><td>runtime role of the backend</td></tr><tr><td><code>OEA_AUDIT_CLEANUP_PASSWORD</code>, <code>OEA_AUDITOR_PASSWORD</code>, <code>OEA_ANALYTICS_PASSWORD</code></td><td>roles for audit retention, audit verification and analytics</td></tr><tr><td><code>OEA_KEK_FILE</code></td><td>path of the key-encryption key file</td></tr><tr><td><code>OEA_HTTP_BIND</code>, <code>OEA_HTTP_PORT</code></td><td>optional: published address, default <code>127.0.0.1:8080</code></td></tr><tr><td><code>OEA_LOG_FORMAT</code></td><td>optional: <code>ecs</code>, <code>logstash</code> or <code>gelf</code> for JSON logs, default plain text (see <a href="./../administration/operations#log-format">Log format</a>)</td></tr><tr><td><code>OEA_TRUSTED_PROXIES</code></td><td>optional: addresses of your reverse proxies, default loopback and the private networks (see <a href="#reverse-proxy">Reverse proxy</a>)</td></tr></tbody></table></li><li><p>Create the key-encryption key. It encrypts stored secrets (second factors, client secrets of identity providers). Keep it outside the database backups:</p><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">head</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 32</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/urandom</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> base64</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /secure/path/oea-kek.key</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0444</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /secure/path/oea-kek.key</span></span></code></pre></div></li><li><p>Start OEA:</p><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>On the first start, PostgreSQL runs the provisioning script and creates the database roles. Then the migration step creates the schema, and the backend starts.</p></li><li><p>Check that the instance is up:</p><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8080/api/v1/health</span></span></code></pre></div><p>The answer contains only the overall status <code>UP</code> or <code>DOWN</code>. The web portal is at <code>http://127.0.0.1:8080/</code>.</p></li></ol><p>Continue with the <a href="./first-administrator">first administrator</a>.</p><div class="warning custom-block"><p class="custom-block-title">Public access</p><p>Do not make the instance reachable from the internet before the setup phase has ended (see <a href="./first-administrator">First administrator</a>). Put a reverse proxy with TLS in front of OEA: the portal needs <code>https</code>, because the session cookie is <code>Secure</code> and the backend sends <code>Strict-Transport-Security</code>. Set the public address with <code>OEA_WEB_PUBLIC_URL</code> (<code>https</code>) before you connect an identity provider.</p></div><h2 id="reverse-proxy" tabindex="-1">Reverse proxy <a class="header-anchor" href="#reverse-proxy" aria-label="Permalink to “Reverse proxy”">​</a></h2><p>OEA takes the address of the client, the scheme and the host from headers that the reverse proxy sets. It needs them to throttle failed logins per client, to record the client address in the audit trail and to check the <code>Origin</code> of changes against the public address. Your proxy must set these headers on every request and overwrite any value the client sent:</p><table tabindex="0"><thead><tr><th>Header</th><th>Value</th></tr></thead><tbody><tr><td><code>X-Forwarded-For</code></td><td>address of the client; append it if the header already exists</td></tr><tr><td><code>X-Forwarded-Proto</code></td><td><code>https</code></td></tr><tr><td><code>X-Forwarded-Host</code></td><td>public host name, for example <code>oea.example.org</code></td></tr><tr><td><code>X-Forwarded-Port</code></td><td>public port; leave it out for 443</td></tr></tbody></table><p>OEA honors these headers only when the request comes from a trusted proxy. By default, it trusts loopback (<code>127.0.0.0/8</code>, <code>::1</code>) and the private networks (<code>10.0.0.0/8</code>, <code>172.16.0.0/12</code>, <code>192.168.0.0/16</code>, <code>100.64.0.0/10</code>, <code>169.254.0.0/16</code>, <code>fc00::/7</code>, <code>fe80::/10</code>). This covers a proxy on the same host as the Compose setup, which connects through the gateway of the Compose network. From any other address, the headers are ignored.</p><p>If clients can reach the backend port directly from a private network, narrow the list with <code>OEA_TRUSTED_PROXIES</code>, a comma-separated list of addresses or CIDR ranges of your proxies:</p><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OEA_TRUSTED_PROXIES</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">172.18.0.1/32,10.20.0.5</span></span></code></pre></div><p>An invalid value stops the start, and the log names <code>OEA_TRUSTED_PROXIES</code>.</p><p>A minimal nginx configuration:</p><div class="language-nginx" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">nginx</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">    listen </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">443</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ssl;</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">    server_name </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">oea.example.org;</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">    # ssl_certificate and ssl_certificate_key of your certificate</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">    location</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> / </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">        proxy_pass </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://127.0.0.1:8080;</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">        proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Host $host;</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">        proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">X-Forwarded-For $proxy_add_x_forwarded_for;</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">        proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">X-Forwarded-Proto https;</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">        proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">X-Forwarded-Host $host;</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">        proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">X-Forwarded-Port </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">443</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="your-own-postgresql" tabindex="-1">Your own PostgreSQL <a class="header-anchor" href="#your-own-postgresql" aria-label="Permalink to “Your own PostgreSQL”">​</a></h2><p>If you use a managed cloud database or an existing cluster, you perform the provisioning and the migration yourself.</p><h3 id="provisioning-once" tabindex="-1">Provisioning (once) <a class="header-anchor" href="#provisioning-once" aria-label="Permalink to “Provisioning (once)”">​</a></h3><p>The script <code>deploy/postgres/initdb/10-oea-roles.sh</code> creates the six database roles, sets their passwords, restricts <code>CONNECT</code> on the database to the OEA roles and creates the schemas with their owners. You need an empty database (default name <code>oea</code>), a role that may create roles, and <code>psql</code> 15 or later:</p><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PGHOST</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">db.example.org PGPORT</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5432</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PGUSER</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">postgres PGPASSWORD</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">...</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> OEA_DB_NAME</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">oea</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> OEA_OWNER_PASSWORD</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">... OEA_REPORTING_OWNER_PASSWORD</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">... OEA_APP_PASSWORD</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">...</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> OEA_AUDIT_CLEANUP_PASSWORD</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">... OEA_AUDITOR_PASSWORD</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">... OEA_ANALYTICS_PASSWORD</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">...</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">deploy/postgres/initdb/10-oea-roles.sh</span></span></code></pre></div><ul><li>The script reads passwords from the environment only; they never appear on the command line or in the output.</li><li>If a password is missing, the script fails and names the missing variables.</li><li>You can run the script again: it resets role attributes, passwords and schema owners, so you can also use it to rotate role passwords.</li><li>Treat every password as a deployment secret: keep it in a secret store, not in your shell history.</li></ul><p>The roles are described in <a href="./../administration/operations#database-roles">Operations</a>.</p><h3 id="migration-before-every-start-of-a-new-version" tabindex="-1">Migration (before every start of a new version) <a class="header-anchor" href="#migration-before-every-start-of-a-new-version" aria-label="Permalink to “Migration (before every start of a new version)”">​</a></h3><p>Schema migrations run in a one-shot step before the backend starts, never inside the running backend:</p><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> oea-backend.jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --oea.migration.url=jdbc:postgresql://db.example.org:5432/oea</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --oea.migration.owner.password=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA_OWNER_PASSWORD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --oea.migration.reporting-owner.password=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA_REPORTING_OWNER_PASSWORD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><p>You can also pass the settings as environment variables (<code>OEA_MIGRATION_URL</code>, <code>OEA_MIGRATION_OWNER_PASSWORD</code>, <code>OEA_MIGRATION_REPORTINGOWNER_PASSWORD</code>); without <code>oea.migration.url</code>, <code>spring.datasource.url</code> is used. The step exits with code <code>0</code> on success and <code>1</code> on any failure.</p><table tabindex="0"><thead><tr><th>Migration set</th><th>Runs as</th><th>Schema history table</th></tr></thead><tbody><tr><td><code>db/migration</code></td><td><code>oea_owner</code></td><td><code>public.flyway_schema_history</code></td></tr><tr><td><code>db/migration-audit</code></td><td><code>oea_owner</code></td><td><code>audit.flyway_schema_history</code></td></tr><tr><td><code>db/migration-reporting</code></td><td><code>oea_reporting_owner</code></td><td><code>reporting.flyway_schema_history</code></td></tr></tbody></table><h3 id="start-the-backend" tabindex="-1">Start the backend <a class="header-anchor" href="#start-the-backend" aria-label="Permalink to “Start the backend”">​</a></h3><p>The backend connects with the runtime role <code>oea_app</code>:</p><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SPRING_DATASOURCE_URL</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">jdbc:postgresql://db.example.org:5432/oea</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SPRING_DATASOURCE_USERNAME=oea_app </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SPRING_DATASOURCE_PASSWORD=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA_APP_PASSWORD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OEA_SECURITY_KEK_CURRENT=/run/secrets/oea_kek </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OEA_WEB_PUBLIC_URL=https://oea.example.org </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">java </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> oea-backend.jar</span></span></code></pre></div><ul><li><code>OEA_WEB_PUBLIC_URL</code> (<code>oea.web.public-url</code>) is the address under which users reach OEA. You need it as soon as an identity provider is enabled; it must use <code>https</code> and must not be a loopback address.</li><li>If the migration step has not run for the current version, the backend refuses to start and names the migration step.</li><li>The backend refuses to start if the key file is missing, unreadable, not exactly 256 bits, or the development key of the repository.</li><li><code>OEA_DATABASE_STATEMENTTIMEOUT</code> (<code>oea.database.statement-timeout</code>, default <code>60s</code>) cancels every database statement of the backend that runs longer; allowed are 1 second to 1 hour. The migration step is not limited.</li><li><code>OEA_CATALOG_QUERYTIMEOUT</code> (<code>oea.catalog.query-timeout</code>, default <code>10s</code>) cancels a catalog query that runs longer; allowed are 1 second up to the statement limit. A cancelled query is answered with 503 <em>Query took too long</em> and written to the audit log as <code>catalog.query-timeout</code>.</li><li>With a value outside these ranges, the backend refuses to start and names the setting.</li></ul>`,33)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};